import{_ as a,o as e,c as o,a3 as t}from"./chunks/framework.DdpBa4_E.js";const r="/ReadBooks/assets/image-003.ISs30jrs.jpeg",s="/ReadBooks/assets/image-004.C7AJwXpJ.jpeg",u=JSON.parse('{"title":"第三章 区分观察和评论","description":"","frontmatter":{},"headers":[],"relativePath":"books/feibaoli-goutong/09-第三章区分观察和评论.md","filePath":"books/feibaoli-goutong/09-第三章区分观察和评论.md","lastUpdated":1795238095000}'),i={name:"books/feibaoli-goutong/09-第三章区分观察和评论.md"};function n(l,p,_,d,h,c){return e(),o("div",null,[...p[0]||(p[0]=[t('<h1 id="第三章-区分观察和评论" tabindex="-1">第三章 区分观察和评论 <a class="header-anchor" href="#第三章-区分观察和评论" aria-label="Permalink to &quot;第三章 区分观察和评论&quot;">​</a></h1><p>我知道如何回应你</p><p>当你说我做了什么或没做什么，</p><p>我也可以回应你的评论，</p><p>但请不要把二者混淆。</p><p>如果你想把任何事情搅浑，</p><p>我可以告诉你怎么做：</p><p>把我做的事情</p><p>和你的反应混为一谈。</p><p>告诉我你感到失望</p><p>当你看到事情还没做完，</p><p>但说我“不负责任”</p><p>并无法打动我。</p><p>告诉我你感到受伤</p><p>当我对你的请求说“不”，</p><p>但说我“冷漠”</p><p>并不会增加你以后的机会。</p><p>是的，我知道如何回应你</p><p>当你说我做了什么或没做什么，</p><p>我也可以回应你的评论，</p><p>但请不要把二者混淆。</p><p>——马歇尔·卢森堡</p><p>非暴力沟通的第一个要素是观察。我们仔细观察正在发生的事情，并清楚地说出观察结果。非暴力沟通并不要求我们保持完全的客观而不作任何评论。它只是强调区分观察和评论的重要性。将观察和评论混为一谈，人们将倾向于听到批评，甚至会产生逆反心理。</p><p>同时，非暴力沟通不鼓励绝对化的评论，而主张评论要基于特定时间和环境中的观察。语义学家温德尔·约翰逊（Wendell Johnson）认为，用静态的语言捕捉变动不居的现实，会造成许多困扰。他讲道：“我们的语言年代久远，但先天不足，是一种有缺陷的工具。它反映了万物有灵论的思想，让我们谈论稳定性和持久性，谈论相似之处、常态和种类，谈论神奇的转变、迅速的痊愈、简单的问题以及终极的解决办法。然而，我们的世界包含着无穷无尽的过程、变化、差别、层面、功能、关系、问题以及复杂性。静态的语言与动态的世界并不匹配，这是我们面临的挑战之一。”</p><p>以下这首歌反映了观察和评论的区别。</p><p>我从未见过懒惰的人；</p><p>我见过</p><p>有个人有时在下午睡觉，</p><p>在雨天不出门，</p><p>但他不是个懒惰的人。</p><p>请在说我胡言乱语之前，</p><p>想一想，他是个懒惰的人，还是</p><p>他的行为被我们称为“懒惰”？</p><p>我从未见过愚蠢的孩子；</p><p>我见过有个孩子有时做的事</p><p>我不理解</p><p>或不按我的吩咐做事情；</p><p>但他不是愚蠢的孩子。</p><p>请在你说他愚蠢之前，</p><p>想一想，他是个愚蠢的孩子，还是</p><p>他懂的事情与你不一样？</p><p>我使劲看了又看</p><p>但从未看到厨师；</p><p>我看到有个人把食物</p><p>调配在一起，</p><p>打起了火，</p><p>看着炒菜的炉子——</p><p>我看到这些但没有看到厨师。</p><p>告诉我，当你看的时候，</p><p>你看到的是厨师，还是有个人</p><p>做的事情被我们称为烹饪？</p><p>我们说有的人懒惰</p><p>另一些人说他们与世无争，</p><p>我们说有的人愚蠢</p><p>另一些人说他学习方法有区别。</p><p>因此，我得出结论，</p><p>如果不把事实</p><p>和意见混为一谈，</p><p>我们将不再困惑。</p><p>因为你可能无所谓，我也想说：</p><p>这只是我的意见。</p><p>——鲁思·贝本梅尔</p><p>负面标签的消极影响很明显——例如用“懒惰”和“愚蠢”这样的词形容人。然而，正面或中性的标签也会妨碍我们全面了解一个人，例如用“厨师”一词定义人。</p><h2 id="人类智力的最高形式" tabindex="-1">人类智力的最高形式 <a class="header-anchor" href="#人类智力的最高形式" aria-label="Permalink to &quot;人类智力的最高形式&quot;">​</a></h2><p>印度哲学家克里希那穆提（J.Krishnamurti）曾经说，“不带评论的观察是人类智力的最高形式。”第一次听到这个观点时，“胡说八道”这个想法在我脑中一闪而过——在不知不觉中，我作出了评论。对于大多数的人来说，观察他人及其行为，而不评判、指责或以其他方式进行分析，是难以做到的。</p><p>在为一个小学提供咨询服务时，我对此有了深刻的体会。这个学校的教师和校长经常反映彼此很难沟通。于是，学区负责人请我协调双方的矛盾。我先和全体教师交谈，然后请校长来参加讨论。</p><p>会谈一开始，我就问：“校长的哪些行为不符合你们的需要？”“他是个大嘴巴。”有人马上回答。我的问题是想了解他们的观察——校长说了什么或做了什么，而“大嘴巴”只是这位教师对校长的评价。</p><p>在我指出这一点后，第二位教师补充说：“我知道他是什么意思。校长的话太多了！”这仍是一个评论——评论校长话多还是话少。随后，第三位教师说：“他认为只有他的话有价值。”我解释说，推测别人想什么与观察他的行为并不是一回事。最后，第四位教师也表明了看法：“他希望所有的人都一直听他讲话。”当我说这也是猜测时，有两位教师脱口而出：“你的问题真难回答啊！”</p><p>接着，我们注意区分观察和评论，一起列出了校长的具体行为。例如，在全体教员会议中，校长会讲他的童年和战时经历，有时导致会议超时20分钟。我问他们是否已向校长反映问题，他们说，他们试过，但从没有提及具体行为——例如校长在会议中回忆往事。最后，他们同意，在校长参加讨论时，指出这些行为。</p><p>与校长的会谈开始后，我很快就发现教师们一直在说的事情。不论讨论的主题是什么，校长总是插话：“这让我想到……”然后，他就开始讲他的童年和战时经历。我等着教师们说出他们的不快。然而，他们运用的不是非暴力沟通，而是无声的抗议。一些人滴溜溜转着眼睛；另一些人故意打着哈欠；还有个人直盯着手表。</p><p>我忍耐着这痛苦的场面，过了一会儿，我问道：“没有人有话要说吗？”接着是有些别扭的沉默。后来，在之前会谈中率先发言的那位教师鼓起勇气，冲着校长说：“你是个大嘴巴！”</p><p>可见，不受旧习惯束缚，学会区分观察和评论，并不容易。最后，教师们终于告诉校长，他在做哪些事时，他们会感到不安。校长听后抱怨说：“为什么从没有人提醒我呢？”他承认他有讲故事的习惯。然而，他接着就开始说与这个习惯有关的故事！这时，我提醒了他。会谈结束时，我们总结了几个办法。一旦教师们不想听校长回忆往事，就温和地提醒他。</p><h2 id="区分观察和评论" tabindex="-1">区分观察和评论 <a class="header-anchor" href="#区分观察和评论" aria-label="Permalink to &quot;区分观察和评论&quot;">​</a></h2><p>在以下的表格中，我举例说明如何区分观察和评论。</p><p><img src="'+r+'" alt="观察与评论混淆对照表" loading="lazy"></p><p>注意：“每次”“曾”等词语在以下句子中表达的是观察结果。</p><p>·我看安迪打了几次电话，每次都至少打半小时。</p><p>·我不记得你曾写信给我。</p><p>“总是”、“从不”等词语在以下句子中表达的是评论。</p><p>·你总是很忙。</p><p>·在需要她的时候，她从不出现。</p><p>如果我们的表达言过其实，别人就可能产生逆反心理，而不愿作出友善的回应。</p><p>“经常”和“很少”这样的词语也可能混淆观察和评论。</p><p><img src="'+s+'" alt="经常很少等词语混淆观察与评论对照表" loading="lazy"></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>非暴力沟通的第一个要素是观察。将观察和评论混为一谈，别人就会倾向于听到批评，并反驳我们。非暴力沟通是动态的语言，不主张绝对化的结论。它提倡在特定的时间和情境中进行观察，并清楚地描述观察结果。例如，它会说“欧文在过去的5场比赛中没有进一个球”，而不是说“欧文是个差劲的前锋”。</p><p>非暴力沟通实例</p><p>“我们遇到的最傲慢的演讲者”</p><p>以下的对话来自我主持的一个研讨班。在讲解了半小时后，我停下来请学员反馈意见。这时，有个人举起了手，他说：“你是我们遇到的最傲慢的演讲者！”</p><p>如果有人这样对我说话，我的反应有几种可能。其中之一是认为自己确实有问题。我知道，一旦我想为自己辩护或开脱，我就默认了自己有问题。另一种反应是把对方的话视为攻击而给予反击。这一次，我既没有辩解也没有指责对方，而用心理解为什么他会这么说。</p><p>我：（猜测他的观察结果）“你这么说，是针对我讲了半小时才请你们发表意见？”</p><p>他：“不是。是因为你把事情说得太简单了。”</p><p>我：（请他澄清）“那么，针对的是，我没有说有些人可能难以运用这个模式？”</p><p>他：“不，不是有些人，而是你自己！”</p><p>我：“那么，你这么说是针对我没有提到有时我也很难运用这个模式？”</p><p>他：“正是。”</p><p>我：“你感到不高兴是因为你希望我在前面的讲演中提到我的困难？”</p><p>他：（停了一下）“正是。”</p><p>我：（了解他的感受和需要后，我开始关注他的请求。）“你希望我现在就承认有时我也很难运用这个模式？”</p><p>他：“是的。”</p><p>我：（了解他的观察、感受、需要和请求后，我问自己是否愿意满足他的请求。）“是的，使用这个模式，我经常会遇到困难。在这个研讨接下来的时间里，你也许会听到我介绍我遇到的几次困难……有时甚至是完全忘记我刚才提及的模式……是什么使我继续努力运用它呢？那是因为一旦我成功运用它，我与他人的感情就加深了。”</p><h2 id="练习一-观察或评论" tabindex="-1">练习一：观察或评论？ <a class="header-anchor" href="#练习一-观察或评论" aria-label="Permalink to &quot;练习一：观察或评论？&quot;">​</a></h2><p>完成以下的练习，看看自己是否可以熟练区分观察和评论。请标出那些只是描述观察结果而不含任何评论的句子。</p><p>1.“哥哥昨天无缘无故对我发脾气。”</p><p>2.“昨晚妹妹在看电视时啃指甲。”</p><p>3.“开会时，经理没有问我的意见。”</p><p>4.“我父亲是个好人。”</p><p>5.“迈克的工作时间太长了。”</p><p>6.“亨利很霸道。”</p><p>7.“本周彼得每天都排在最前面。”</p><p>8.“我儿子经常不刷牙。”</p><p>9.“里奇告诉我，我穿黄色衣服不好看。”</p><p>10.“姑姑在和我说话时爱发牢骚。”</p><p>以下是我对练习一的理解：</p><p>1.如果你认为这一句是观察，我们意见不一致。我认为“无缘无故”是评论。此外，我认为说哥哥发脾气了也是评论。他也可能是感到害怕、悲伤或别的。以下例句描述了观察结果而不含任何评论：“哥哥告诉我，他生气了。”或是“哥哥用拳头砸了一下桌子。”</p><p>2.如果你认为这一句是观察，我们意见一致。</p><p>3.如果你认为这一句是观察，我们意见一致。</p><p>4.如果你认为这一句是观察，我们意见不一致。我认为“好人”是评论。以下例句描述了观察结果而不含任何评论：“在过去的25年中，父亲将他工资收入的十分之一捐给了慈善机构。”</p><p>5.如果你认为这一句是观察，我们意见不一致。我认为“太长了”是评论。以下例句描述了观察结果而不含任何评论：“本周迈克在办公室工作了60小时以上。”</p><p>6.如果你认为这一句是观察，我们意见不一致。我认为“很霸道”是评论。以下例句描述了观察结果而不含任何评论：“亨利在他姐姐换电视节目频道时，撞了她一下。”</p><p>7.如果你认为这一句是观察，我们意见一致。</p><p>8.如果你认为这一句是观察，我们意见不一致。我认为“经常”是评论。以下例句描述了观察结果而不含任何评论：“本周我儿子有两次没刷牙就上床睡觉。”</p><p>9.如果你认为这一句是观察，我们意见一致。</p><p>10.如果你认为这一句是观察，我们意见不一致。我认为“爱发牢骚”是评论。以下例句描述了观察结果而不含任何评论：“本周姑姑给我打了三次电话，每次都说别人不尊重她。”</p><p>面具</p><p>总是一副面具</p><p>由纤细白皙的手举着</p><p>挡在脸前，</p><p>那轻轻举着面具</p><p>的手腕</p><p>十分灵巧：</p><p>虽然有时</p><p>有点颤抖，</p><p>指尖抖动，</p><p>但总是</p><p>能把面具举好。</p><p>年复一年我不禁好奇</p><p>但不敢问</p><p>终于</p><p>无意中</p><p>看到了面具背后</p><p>却</p><p>什么也没有。</p><p>她没有脸。</p><p>她已成了</p><p>优雅地</p><p>举着面具的手。</p><p>——佚名</p>',148)])])}const b=a(i,[["render",n]]);export{u as __pageData,b as default};
